{
  "technical_and_design_decisions": [
    "Implement the functionality in the existing Hyperledger Fabric channel-configuration library and follow its current ConfigTx, ConfigGroup, ConfigUpdate, and config package conventions.",
    "Add explicit helpers for adding and removing orderer endpoints from an orderer organization configuration group, preserving existing configuration values and producing a standard ConfigUpdate through the library's existing update mechanism.",
    "Treat endpoint removal as an exact endpoint-value removal and make addition idempotent so the same endpoint is not duplicated.",
    "Expose organization policy retrieval through a helper that works for application, orderer, and consortium organizations without requiring callers to traverse the raw configuration tree.",
    "Expose retrieval of channel, application, and orderer capabilities as config.Capabilities values.",
    "Use explicit enable and disable helpers for the supported application, orderer, and channel capabilities already represented by the Fabric version in use, rather than allowing arbitrary unsupported capability strings.",
    "Expose application configuration retrieval as a config.Application value and preserve the existing configuration object semantics.",
    "Implement application ACL changes as add and remove operations against the application group's ACL map, with validation of paths and preservation of unrelated ACLs.",
    "Split the example coverage into focused examples for orderer configuration, application configuration, organization management, MSP changes, and capabilities, while retaining shared setup helpers where useful.",
    "Use existing serialization, validation, and ConfigUpdate computation facilities rather than introducing a new configuration-diff or transaction-generation mechanism."
  ],
  "assumptions": [
    "The work is performed in an existing Go Hyperledger Fabric channel-configuration codebase with working build, test, protobuf, and configuration helper infrastructure.",
    "The specification does not require changes to Fabric peer, orderer, consensus, MSP, or network runtime components; only the channel-configuration library and its examples/tests are changed.",
    "Existing public API naming and backward-compatibility conventions can be followed without a separate major-version redesign.",
    "The supported capability constants and policy/configuration types already exist in the repository or in the current Fabric dependency version.",
    "Existing example fixtures contain valid channel configuration data for application organizations, orderer organizations, policies, ACLs, endpoints, MSPs, and capabilities.",
    "Acceptance testing consists of unit and example/integration-style tests that construct or modify Config transactions and verify subsequent ConfigUpdate processing; no deployment of a live multi-node Fabric network is required.",
    "No new external dependencies, generated protobuf definitions, or persistent storage changes are needed.",
    "Code review, formatting, static analysis, and the repository's normal test suite are included in the estimate.",
    "Estimates represent active individual developer effort in work-hours, including implementation, debugging, and test updates, not elapsed calendar time."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Codebase discovery and implementation planning",
      "activity_description": "Review the existing channel-configuration API, configuration data model, update/diff generation flow, supported Fabric capability types, test fixtures, and current end-to-end example. Identify reusable helpers and compatibility constraints.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2",
      "activity_name": "API and behavior design",
      "activity_description": "Define public helper signatures, return types, mutation semantics, idempotency and validation behavior, capability enable/disable API shape, policy lookup behavior, ACL handling, and ConfigUpdate workflow integration for U1-U7.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A3",
      "activity_name": "Orderer endpoint add and remove support",
      "activity_description": "Implement helpers to add and remove orderer endpoints in an orderer organization's config group, preserve unrelated values, handle duplicate or missing endpoints consistently, and integrate the changes with ConfigUpdate generation and subsequent processing.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "A4",
      "activity_name": "Organization policy retrieval support",
      "activity_description": "Implement organization policy retrieval that works for application, orderer, and consortium organizations, including organization lookup, policy extraction, absent-policy handling, and conversion to the library's public policy representation.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A5",
      "activity_name": "Capability retrieval and mutation support",
      "activity_description": "Implement retrieval of channel, application, and orderer capabilities as config.Capabilities and add supported capability enable/disable operations with validation, mutation tracking, and compatibility with later configuration updates.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A6",
      "activity_name": "Application configuration retrieval",
      "activity_description": "Implement a helper that locates and returns existing application configuration as config.Application, including appropriate behavior when the application group or expected values are absent.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A7",
      "activity_name": "Application ACL add and remove support",
      "activity_description": "Implement application-group ACL add and remove operations, validate ACL keys and values, preserve unrelated ACL entries, and ensure the modified configuration can be used for additional updates and ConfigUpdate generation.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "A8",
      "activity_name": "Focused example restructuring and additions",
      "activity_description": "Replace the oversized configuration-update example flow with smaller examples covering orderer configuration and policies, application values and policies, organization management, MSP modifications, and capabilities; add focused demonstrations for endpoints, policies, ACLs, and retrieval helpers.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A9",
      "activity_name": "Unit and acceptance test implementation",
      "activity_description": "Add targeted tests for endpoint operations, policy and configuration retrieval, capabilities, ACL changes, edge cases, idempotency, and processing further updates from modified configurations. Verify generated ConfigUpdates are suitable for signature workflows.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "A10",
      "activity_name": "Documentation, API comments, and usage review",
      "activity_description": "Add or update exported API comments, clarify mutation and error behavior, review examples for usability, and ensure the public API is consistent with existing library documentation conventions.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A11",
      "activity_name": "Build, static checks, integration validation, and defect correction",
      "activity_description": "Run formatting, compilation, static analysis, the complete relevant test suite, and example validation; diagnose and correct integration issues, API compatibility problems, or test failures found during final verification.",
      "most_likely_effort": 6
    }
  ],
  "reported_total": {
    "most_likely_effort": 128
  }
}

